"""Resumable, one-user Memotron graph backfill and inference pipeline."""
import argparse
import gzip
import hashlib
import json
import os
import re
import time
from collections import defaultdict
from decimal import Decimal
from pathlib import Path

import boto3
import httpx
import psycopg
from boto3.dynamodb.conditions import Key
from psycopg.types.json import Jsonb

ROOT = Path(__file__).resolve().parents[1]
RESOURCES = ("node", "file", "link", "collection", "property", "linkTag")
PROFILE_VERSION = "profile-v1"
RELATION_VERSION = "relation-v1"


def config():
    """Load ignored local credentials and validate the SQL namespace."""
    for line in (ROOT / ".env").read_text().splitlines():
        if line and not line.startswith("#") and "=" in line:
            key, value = line.split("=", 1)
            os.environ.setdefault(key.strip(), value.strip().strip('"').strip("'"))
    schema = os.environ.get("MGRAPH_DATABASE_SCHEMA", "mgraph_pilot")
    if not re.fullmatch(r"[a-z][a-z0-9_]*", schema):
        raise ValueError("Invalid database schema")
    return schema


def canonical(value):
    """Serialize DynamoDB records deterministically, preserving numeric values."""
    def default(item):
        if isinstance(item, Decimal):
            return float(item) if item % 1 else int(item)
        if isinstance(item, (bytes, bytearray)):
            return {"base64": __import__("base64").b64encode(item).decode()}
        raise TypeError(type(item).__name__)
    return json.dumps(value, sort_keys=True, ensure_ascii=False, separators=(",", ":"), default=default)


def sha(value):
    return hashlib.sha256(value.encode() if isinstance(value, str) else value).hexdigest()


def database():
    return psycopg.connect(os.environ["MGRAPH_DATABASE_URL"])


def source():
    session = boto3.Session(profile_name=os.environ.get("MGRAPH_SOURCE_AWS_PROFILE", "phidata"), region_name=os.environ.get("MGRAPH_SOURCE_AWS_REGION", "ap-south-1"))
    return session.resource("dynamodb").Table(os.environ["MGRAPH_SOURCE_DYNAMODB_TABLE"])


def storage():
    return boto3.client("s3", endpoint_url=os.environ["MGRAPH_R2_ENDPOINT"], region_name=os.environ.get("MGRAPH_R2_REGION", "auto"), aws_access_key_id=os.environ["MGRAPH_R2_ACCESS_KEY_ID"], aws_secret_access_key=os.environ["MGRAPH_R2_SECRET_ACCESS_KEY"])


def object_key(kind, name):
    prefix = os.environ.get("MGRAPH_R2_PREFIX", "mgraph-pilot/").strip("/")
    return f"{prefix}/{os.environ['MGRAPH_SOURCE_USER_ID']}/{kind}/{name}"


def migrate(schema):
    """Create the isolated pilot schema and pgvector extension."""
    sql = (ROOT / "sql" / "001_init.sql").read_text().format(schema=schema)
    with database() as conn:
        conn.execute(sql)
    print("migration applied")


def backfill(schema, page_limit):
    """Read DynamoDB account partitions and checkpoint compressed R2 pages."""
    table, r2 = source(), storage()
    with database() as conn:
        for resource in RESOURCES:
            cursor, page, total = None, 0, 0
            while True:
                request = {"KeyConditionExpression": Key("PK").eq(os.environ["MGRAPH_SOURCE_USER_ID"] + "#" + resource), "ConsistentRead": True, "Limit": 500}
                if cursor:
                    request["ExclusiveStartKey"] = cursor
                response = table.query(**request)
                records = [json.loads(canonical(item)) for item in response["Items"]]
                raw = ("\n".join(canonical(item) for item in records) + "\n").encode()
                key = object_key("dynamodb", f"{resource}/page-{page:05d}-{sha(raw)[:16]}.jsonl.gz")
                r2.put_object(Bucket=os.environ["MGRAPH_R2_BUCKET"], Key=key, Body=gzip.compress(raw), ContentType="application/gzip", Metadata={"sha256": sha(raw)})
                with conn.cursor() as cur:
                    for item in records:
                        record_id = str(item.get("id") or item.get("SK"))
                        cur.execute(f"INSERT INTO {schema}.source_record(resource,id,payload,sha256) VALUES (%s,%s,%s,%s) ON CONFLICT(resource,id) DO UPDATE SET payload=excluded.payload,sha256=excluded.sha256,ingested_at=now() WHERE {schema}.source_record.sha256<>excluded.sha256", (resource, record_id, Jsonb(item), sha(canonical(item))))
                    cur.execute(f"INSERT INTO {schema}.snapshot_page(resource,page_number,r2_key,sha256,row_count) VALUES (%s,%s,%s,%s,%s) ON CONFLICT(resource,page_number) DO UPDATE SET r2_key=excluded.r2_key,sha256=excluded.sha256,row_count=excluded.row_count,created_at=now()", (resource, page, key, sha(raw), len(records)))
                conn.commit()
                total += len(records)
                page += 1
                print(f"{resource}: {total} records, {page} pages", flush=True)
                cursor = response.get("LastEvaluatedKey")
                if not cursor or (page_limit and page >= page_limit):
                    break


def parse_legacy(value):
    if isinstance(value, str) and value[:1] in ("{", "["):
        try:
            return json.loads(value)
        except json.JSONDecodeError:
            pass
    return value


def text_parts(value):
    """Extract text from legacy serialized bodies without treating IDs as prose."""
    value = parse_legacy(value)
    if isinstance(value, str):
        return [value] if value and len(value) <= 100000 else []
    if isinstance(value, list):
        return [part for item in value for part in text_parts(item)]
    if isinstance(value, dict):
        return [part for key in ("text", "description", "transcription", "quote", "title", "value", "content", "markdown") for part in text_parts(value[key])] if any(key in value for key in ("text", "description", "transcription", "quote", "title", "value", "content", "markdown")) else []
    return []


def project(schema):
    """Build root entries with evidence from all reachable child blocks."""
    with database() as conn:
        nodes = {record_id: data for record_id, data in conn.execute(f"SELECT id,payload FROM {schema}.source_record WHERE resource='node'")}
        files = {record_id: data for record_id, data in conn.execute(f"SELECT id,payload FROM {schema}.source_record WHERE resource='file'")}
        children, roots = defaultdict(list), []
        for item in nodes.values():
            parent = item.get("creationContext") or item.get("parent")
            (children[parent] if parent else roots).append(item)
        for count, root in enumerate(roots, 1):
            queue, descendants, seen = list(children.get(root["id"], [])), [], {root["id"]}
            while queue and len(descendants) < 2000:
                child = queue.pop(0)
                if child["id"] in seen:
                    continue
                seen.add(child["id"])
                descendants.append(child)
                queue.extend(children.get(child["id"], []))
            evidence, refs = [], []
            for item in [root] + descendants:
                fragments = [part for key in ("label", "text", "notes", "url", "body", "metadata") for part in text_parts(item.get(key))]
                file_id = item.get("file")
                if file_id in files:
                    fragments.extend(text_parts(files[file_id].get("label")))
                snippet = "\n".join(dict.fromkeys(part.strip() for part in fragments if isinstance(part, str) and part.strip()))
                if snippet:
                    evidence.append(snippet[:12000])
                    refs.append({"id": item["id"], "contentType": item.get("contentType"), "file": file_id})
            content = "\n\n".join(evidence)[:90000]
            quality = "rich" if len(content) >= 400 else "thin" if content else "empty"
            source_hash = sha(canonical([root, descendants]))
            conn.execute(f"INSERT INTO {schema}.entry(id,content_type,label,url,source_hash,evidence_text,evidence_refs,evidence_quality) VALUES (%s,%s,%s,%s,%s,%s,%s,%s) ON CONFLICT(id) DO UPDATE SET content_type=excluded.content_type,label=excluded.label,url=excluded.url,source_hash=excluded.source_hash,evidence_text=excluded.evidence_text,evidence_refs=excluded.evidence_refs,evidence_quality=excluded.evidence_quality,updated_at=now() WHERE {schema}.entry.source_hash<>excluded.source_hash", (root["id"], root.get("contentType", "UNKNOWN"), root.get("label"), root.get("url"), source_hash, content, Jsonb(refs), quality))
            if count % 500 == 0:
                conn.commit()
                print(f"projected {count}", flush=True)
        conn.commit()
        print(f"projected {len(roots)} root entries")


def do_chat(model, messages, tokens=1400):
    """Call DigitalOcean serverless chat and return text, usage, and latency."""
    started = time.monotonic()
    url = os.environ.get("MGRAPH_DO_BASE_URL", "https://inference.do-ai.run").rstrip("/") + "/v1/chat/completions"
    with httpx.Client(timeout=120) as client:
        response = client.post(url, headers={"Authorization": "Bearer " + os.environ["MGRAPH_DO_MODEL_ACCESS_KEY"]}, json={"model": model, "messages": messages, "max_tokens": tokens, "temperature": 0})
        response.raise_for_status()
        result = response.json()
    return result["choices"][0]["message"].get("content") or "", result.get("usage", {}), time.monotonic() - started


def model_json(raw):
    raw = re.sub(r"^```(?:json)?\s*|\s*```$", "", raw.strip())
    return json.loads(raw)


def profile_prompt(entry_id, kind, content):
    return [{"role": "system", "content": "Create an evidence-grounded memory profile. Return only JSON with keys: summary (string), concepts (array of short strings), tags (array of short strings), properties (object of stable factual fields), claims (array of objects with text and evidence_id), domains (array of strings), uncertainty (array of strings). Do not infer unsupported product capabilities. Distinguish specific niche from broad domain. Every claim must cite the supplied evidence_id. Keep output compact."}, {"role": "user", "content": canonical({"evidence_id": entry_id, "content_type": kind, "source": content[:13000]})}]


def profile(schema, limit, model):
    """Derive versioned profiles from source and extraction evidence."""
    with database() as conn:
        rows = conn.execute(f"SELECT e.id,e.content_type,e.evidence_text,e.source_hash,coalesce(string_agg(x.text_content,E'\\n'),'') AS extracted,p.source_hash,p.prompt_version FROM {schema}.entry e LEFT JOIN {schema}.extraction x ON x.entry_id=e.id LEFT JOIN {schema}.profile p ON p.entry_id=e.id GROUP BY e.id,p.source_hash,p.prompt_version ORDER BY e.id").fetchall()
        completed = 0
        for entry_id, kind, source_text, source_hash, extracted, old_hash, old_version in rows:
            content = (source_text + "\n" + extracted).strip()
            combined_hash = sha(source_hash + sha(extracted))
            if len(content) < 40 or (combined_hash == old_hash and old_version == PROFILE_VERSION):
                continue
            try:
                raw, usage, latency = do_chat(model, profile_prompt(entry_id, kind, content))
                result = model_json(raw)
                if not isinstance(result.get("concepts"), list) or not isinstance(result.get("claims"), list):
                    raise ValueError("invalid profile shape")
                embedding_text = "\n".join([result.get("summary", ""), "Concepts: " + ", ".join(result.get("concepts", [])[:20]), "Tags: " + ", ".join(result.get("tags", [])[:20]), "Claims: " + "; ".join(str(claim.get("text", "")) for claim in result.get("claims", [])[:15])])
                conn.execute(f"INSERT INTO {schema}.profile(entry_id,source_hash,model,profile,text_for_embedding,prompt_version) VALUES (%s,%s,%s,%s,%s,%s) ON CONFLICT(entry_id) DO UPDATE SET source_hash=excluded.source_hash,model=excluded.model,profile=excluded.profile,text_for_embedding=excluded.text_for_embedding,prompt_version=excluded.prompt_version,updated_at=now()", (entry_id, combined_hash, model, Jsonb(result), embedding_text, PROFILE_VERSION))
                conn.commit()
                completed += 1
                print(f"profile {completed}: {entry_id} {latency:.1f}s {usage}", flush=True)
            except (httpx.HTTPError, ValueError, KeyError) as error:
                conn.rollback()
                print(f"profile failed {entry_id}: {type(error).__name__}: {str(error)[:150]}", flush=True)
            if limit and completed >= limit:
                break


def cf_embed(content):
    """Generate a 1024-dimensional Workers AI embedding."""
    model = os.environ.get("MGRAPH_CF_EMBEDDING_MODEL", "@cf/qwen/qwen3-embedding-0.6b")
    url = f"https://api.cloudflare.com/client/v4/accounts/{os.environ['MGRAPH_CLOUDFLARE_ACCOUNT_ID']}/ai/run/{model}"
    with httpx.Client(timeout=90) as client:
        response = client.post(url, headers={"Authorization": "Bearer " + os.environ["MGRAPH_CLOUDFLARE_WORKERS_AI_API_TOKEN"]}, json={"text": [content[:8000]]})
        response.raise_for_status()
        result = response.json()["result"]
    vector = result["data"][0] if isinstance(result, dict) and "data" in result else result[0]
    if len(vector) != 1024:
        raise ValueError("embedding dimension mismatch")
    return vector


def embed(schema, limit):
    model = os.environ.get("MGRAPH_CF_EMBEDDING_MODEL", "@cf/qwen/qwen3-embedding-0.6b")
    with database() as conn:
        rows = conn.execute(f"SELECT p.entry_id,p.text_for_embedding,e.profile_hash FROM {schema}.profile p LEFT JOIN {schema}.embedding e ON e.entry_id=p.entry_id ORDER BY p.entry_id").fetchall()
        count = 0
        for entry_id, content, old_hash in rows:
            content_hash = sha(content)
            if old_hash == content_hash:
                continue
            try:
                vector = cf_embed(content)
                conn.execute(f"INSERT INTO {schema}.embedding(entry_id,profile_hash,model,vector) VALUES (%s,%s,%s,%s::vector) ON CONFLICT(entry_id) DO UPDATE SET profile_hash=excluded.profile_hash,model=excluded.model,vector=excluded.vector,updated_at=now()", (entry_id, content_hash, model, canonical(vector)))
                conn.commit()
                count += 1
                print(f"embedded {count}: {entry_id}", flush=True)
            except (httpx.HTTPError, ValueError, KeyError) as error:
                conn.rollback()
                print(f"embedding failed {entry_id}: {type(error).__name__}: {str(error)[:150]}", flush=True)
            if limit and count >= limit:
                break


def relation_prompt(left, right):
    return [{"role": "system", "content": "Compare two saved memory entries for graph proximity. Return only JSON with score (number 0..1), relation (same_product|same_niche|related_domain|conceptual_echo|contradiction|unrelated), shared_concepts (array), distinguishing_facts (array), explanation (string), evidence_ids (array). Be conservative: two coding tools are broadly related, while two agentic development environments are a tighter niche. Cite both entry IDs. Do not invent features absent from evidence."}, {"role": "user", "content": canonical({"left": left, "right": right})}]


def candidate_pairs(schema, per_entry, max_pairs):
    """Union vector neighbors, lexical matches, and explicit source links."""
    pairs = set()
    with database() as conn:
        vectors = conn.execute(f"SELECT entry_id,vector::text FROM {schema}.embedding ORDER BY entry_id").fetchall()
        for entry_id, vector in vectors:
            neighbors = conn.execute(f"SELECT entry_id FROM {schema}.embedding WHERE entry_id<>%s ORDER BY vector <=> %s::vector LIMIT %s", (entry_id, vector, per_entry)).fetchall()
            pairs.update(tuple(sorted((entry_id, row[0]))) for row in neighbors)
            lexical = conn.execute(f"SELECT id FROM {schema}.entry WHERE id<>%s AND to_tsvector('english', evidence_text) @@ plainto_tsquery('english', (SELECT left(coalesce(label,''),80) FROM {schema}.entry WHERE id=%s)) LIMIT %s", (entry_id, entry_id, per_entry)).fetchall()
            pairs.update(tuple(sorted((entry_id, row[0]))) for row in lexical)
        for left, right in conn.execute(f"SELECT payload->>'out',payload->>'in' FROM {schema}.source_record WHERE resource='link'"):
            if left and right and left != right:
                pairs.add(tuple(sorted((left, right))))
    return sorted(pairs)[:max_pairs] if max_pairs else sorted(pairs)


def relate(schema, limit, model, per_entry):
    with database() as conn:
        count = 0
        for left_id, right_id in candidate_pairs(schema, per_entry, limit * 8 if limit else None):
            rows = conn.execute(f"SELECT e.id,e.content_type,e.label,p.profile,e.evidence_text FROM {schema}.entry e LEFT JOIN {schema}.profile p ON p.entry_id=e.id WHERE e.id IN (%s,%s) ORDER BY e.id", (left_id, right_id)).fetchall()
            if len(rows) != 2 or not all(row[3] for row in rows):
                continue
            payloads = [{"evidence_id": row[0], "type": row[1], "label": row[2], "profile": row[3], "excerpt": row[4][:1200]} for row in rows]
            pair_hash = sha(canonical(payloads) + RELATION_VERSION)
            old = conn.execute(f"SELECT source_hash FROM {schema}.relation WHERE left_id=%s AND right_id=%s", (left_id, right_id)).fetchone()
            if old and old[0] == pair_hash:
                continue
            try:
                raw, usage, latency = do_chat(model, relation_prompt(*payloads), 900)
                result = model_json(raw)
                score = float(result["score"])
                if not 0 <= score <= 1:
                    raise ValueError("score out of range")
                conn.execute(f"INSERT INTO {schema}.relation(left_id,right_id,model,source_hash,judgment,score) VALUES (%s,%s,%s,%s,%s,%s) ON CONFLICT(left_id,right_id) DO UPDATE SET model=excluded.model,source_hash=excluded.source_hash,judgment=excluded.judgment,score=excluded.score,updated_at=now()", (left_id, right_id, model, pair_hash, Jsonb(result), score))
                conn.commit()
                count += 1
                print(f"relation {count}: {left_id} {right_id} score={score:.2f} {latency:.1f}s {usage}", flush=True)
            except (httpx.HTTPError, ValueError, KeyError) as error:
                conn.rollback()
                print(f"relation failed {left_id} {right_id}: {type(error).__name__}: {str(error)[:150]}", flush=True)
            if limit and count >= limit:
                break


def status(schema):
    with database() as conn:
        for table in ("source_record", "snapshot_page", "entry", "extraction", "profile", "embedding", "relation"):
            print(f"{table}: {conn.execute(f'SELECT count(*) FROM {schema}.{table}').fetchone()[0]}")
        for kind, count, rich in conn.execute(f"SELECT content_type,count(*),sum(CASE WHEN evidence_quality='rich' THEN 1 ELSE 0 END) FROM {schema}.entry GROUP BY content_type ORDER BY count(*) DESC"):
            print(f"{kind}: {count} entries, {rich} rich")


def main():
    parser = argparse.ArgumentParser(description="Memotron m graph pilot pipeline")
    parser.add_argument("command", choices=("migrate", "backfill", "project", "profile", "embed", "relate", "status"))
    parser.add_argument("--limit", type=int)
    parser.add_argument("--model")
    parser.add_argument("--per-entry", type=int, default=8)
    args = parser.parse_args()
    schema = config()
    if args.command == "migrate":
        migrate(schema)
    elif args.command == "backfill":
        backfill(schema, args.limit)
    elif args.command == "project":
        project(schema)
    elif args.command == "profile":
        profile(schema, args.limit, args.model or os.environ.get("MGRAPH_DO_REASONING_MODEL", "openai-gpt-oss-120b"))
    elif args.command == "embed":
        embed(schema, args.limit)
    elif args.command == "relate":
        relate(schema, args.limit, args.model or os.environ.get("MGRAPH_DO_REASONING_MODEL", "openai-gpt-oss-120b"), args.per_entry)
    else:
        status(schema)
