"""Evidence enrichment for public pages and user-owned media."""
import base64
import io
import ipaddress
import json
import os
import re
import socket
import time
from html.parser import HTMLParser
from urllib.parse import urlparse, urljoin

import httpx
import psycopg
from psycopg.types.json import Jsonb

from .cli import canonical, database, do_chat, object_key, sha, storage


class PageText(HTMLParser):
    """Collect document title, description, headings, and body text."""
    def __init__(self):
        super().__init__()
        self.parts = []
        self.skip = 0
        self.title = ""
        self.in_title = False

    def handle_starttag(self, tag, attrs):
        if tag in ("script", "style", "noscript", "svg"):
            self.skip += 1
        if tag == "title":
            self.in_title = True
        if tag == "meta":
            attributes = dict(attrs)
            if attributes.get("name", "").lower() == "description" or attributes.get("property") == "og:description":
                self.parts.append(attributes.get("content", ""))

    def handle_endtag(self, tag):
        if tag in ("script", "style", "noscript", "svg") and self.skip:
            self.skip -= 1
        if tag == "title":
            self.in_title = False

    def handle_data(self, data):
        text = " ".join(data.split())
        if not text or self.skip:
            return
        if self.in_title:
            self.title += text + " "
        self.parts.append(text)


def public_url(url):
    """Reject private destinations before each public-page request."""
    parsed = urlparse(url)
    if parsed.scheme not in ("http", "https") or not parsed.hostname or parsed.username or parsed.password:
        raise ValueError("unsupported URL")
    for address in socket.getaddrinfo(parsed.hostname, parsed.port or (443 if parsed.scheme == "https" else 80)):
        ip = ipaddress.ip_address(address[4][0])
        if not ip.is_global:
            raise ValueError("nonpublic URL")
    return url


def fetch_page(url):
    with httpx.Client(timeout=18, follow_redirects=False, headers={"User-Agent": "MemotronMGraphPilot/0.1"}) as client:
        for _ in range(4):
            public_url(url)
            response = client.get(url)
            if response.status_code in (301, 302, 303, 307, 308):
                url = urljoin(url, response.headers["location"])
                continue
            response.raise_for_status()
            if "html" not in response.headers.get("content-type", "") or len(response.content) > 3_000_000:
                raise ValueError("unsupported page response")
            parser = PageText()
            parser.feed(response.text)
            content = "\n".join(dict.fromkeys([parser.title.strip()] + parser.parts))[:80000]
            return url, response.content, content
    raise ValueError("too many redirects")


def owned_s3_object(url):
    """Resolve only the legacy user's S3 files, never arbitrary URLs."""
    parsed = urlparse(url)
    expected = "s3." + os.environ.get("MGRAPH_SOURCE_AWS_REGION", "ap-south-1") + ".amazonaws.com"
    if parsed.scheme != "https" or parsed.hostname != expected:
        raise ValueError("not a legacy S3 URL")
    path = parsed.path.lstrip("/")
    bucket, _, key = path.partition("/")
    if not bucket.startswith("tidyfiles") or not key.startswith(os.environ["MGRAPH_SOURCE_USER_ID"] + "/"):
        raise ValueError("S3 object outside user scope")
    return bucket, key


def fetch_owned_file(url, max_bytes=15_000_000):
    from .cli import aws_session
    bucket, key = owned_s3_object(url)
    client = aws_session().client("s3")
    head = client.head_object(Bucket=bucket, Key=key)
    if head["ContentLength"] > max_bytes:
        raise ValueError("file exceeds extractor size limit")
    return client.get_object(Bucket=bucket, Key=key)["Body"].read(max_bytes + 1)


def cf_transcribe(audio):
    model = os.environ.get("MGRAPH_CF_TRANSCRIPTION_MODEL", "@cf/openai/whisper-large-v3-turbo")
