    with httpx.Client(timeout=180) as client:
        response = client.post(url, headers={"Authorization": "Bearer " + os.environ["MGRAPH_CLOUDFLARE_WORKERS_AI_API_TOKEN"]}, json={"audio": base64.b64encode(audio).decode(), "task": "transcribe"})
        response.raise_for_status()
        result = response.json()["result"]
    return result.get("text") or result.get("transcription_info", {}).get("text") or ""


def describe_image(data, mime, model):
    content = [{"type": "text", "text": "Describe visible concepts, objects, diagrams, and readable text for a personal memory graph. Be factual and say when uncertain."}, {"type": "image_url", "image_url": {"url": "data:" + mime + ";base64," + base64.b64encode(data).decode()}}]
    return do_chat(model, [{"role": "user", "content": content}], 750)[0]


def extract_pdf(data):
    from pypdf import PdfReader
    reader = PdfReader(io.BytesIO(data))
    return "\n".join((page.extract_text() or "") for page in reader.pages[:100])[:80000]


