    {"id": "ide-broad", "left": {"evidence_id": "sample:onorca", "label": "Onorca", "excerpt": "Agentic development environment for coding with AI agents."}, "right": {"evidence_id": "sample:vscode", "label": "Visual Studio Code", "excerpt": "General-purpose source code editor and IDE used for software development."}, "expected": "related_domain"},
    {"id": "cross-medium-concept", "left": {"evidence_id": "sample:book", "label": "Book highlight", "excerpt": "When a team reduces the delay between action and feedback, learning accelerates even if the individual actions are imperfect."}, "right": {"evidence_id": "sample:article", "label": "Web article", "excerpt": "Short feedback cycles let teams correct mistakes sooner and improve through repeated experiments."}, "expected": "conceptual_echo"},
    {"id": "unrelated", "left": {"evidence_id": "sample:vscode", "label": "Visual Studio Code", "excerpt": "General-purpose source code editor and IDE used for software development."}, "right": {"evidence_id": "sample:recipe", "label": "Pasta recipe", "excerpt": "Boil pasta until al dente, then mix with tomato sauce and basil."}, "expected": "unrelated"},
)
PRICES = {"glm-5.3": (1.4, 4.4), "kimi-k3": (3.0, 15.0)}


def evaluate(schema):
    """Run identical fixed cases, recording validity, rankings, tokens, and cost."""
    report = {"created_at": datetime.now(timezone.utc).isoformat(), "kind": "synthetic_smoke_not_ground_truth", "models": {}}
    for model in PRICES:
        outcomes = []
        for case in CASES:
            try:
                raw, usage, latency = do_chat(model, relation_prompt(case["left"], case["right"]), 1100)
                result = model_json(raw)
                score = float(result["score"])
                valid = 0 <= score <= 1 and result.get("relation") in ("same_product", "same_niche", "related_domain", "conceptual_echo", "contradiction", "unrelated") and set(result.get("evidence_ids", [])) == {case["left"]["evidence_id"], case["right"]["evidence_id"]}
                in_tokens = usage.get("prompt_tokens", 0)
                out_tokens = usage.get("completion_tokens", 0)
                price = PRICES[model]
                outcome = {"case": case["id"], "expected": case["expected"], "valid": valid, "relation": result.get("relation"), "score": score, "seconds": round(latency, 2), "input_tokens": in_tokens, "output_tokens": out_tokens, "estimated_usd": round((in_tokens * price[0] + out_tokens * price[1]) / 1_000_000, 6), "explanation": result.get("explanation", "")}
            except Exception as error:
                outcome = {"case": case["id"], "expected": case["expected"], "valid": False, "error": type(error).__name__ + ": " + str(error)[:150]}
            outcomes.append(outcome)
            print(model, case["id"], canonical({k: v for k, v in outcome.items() if k not in ("explanation", "error")}), flush=True)
        scores = {item["case"]: item.get("score") for item in outcomes}
        valid_scores = all(value is not None for value in scores.values())
        report["models"][model] = {"cases": outcomes, "all_valid": all(item["valid"] for item in outcomes), "ordering_correct": valid_scores and scores["ade-close"] > scores["ide-broad"] > scores["unrelated"] and scores["cross-medium-concept"] > scores["unrelated"], "exact_relation_matches": sum(item.get("relation") == item["expected"] for item in outcomes), "estimated_usd": round(sum(item.get("estimated_usd", 0) for item in outcomes), 6)}
    path = ROOT / "evaluation.json"
    path.write_text(json.dumps(report, indent=2) + "\n")
    print("evaluation written:", path)
