+function layoutGroup(group, groupEdges, constraints, width, height) {
+  const columns = Math.max(1, Math.ceil(Math.sqrt(group.length)));
+  const rows = Math.max(1, Math.ceil(group.length / columns));
+  const points = group.map((node, index) => ({id: node.id, x: width * (index % columns + 1) / (columns + 1), y: height * (Math.floor(index / columns) + 1) / (rows + 1)}));
+  if (group.length === 1) return points;
+  if (group.length > 60) return points;
+  const lookup = new Map(points.map((point, index) => [point.id, index]));
+  const strengths = new Map(groupEdges.map(edge => [[edge.left, edge.right].sort().join('|'), edge.score]));
+  for (let step = 0; step < 100; step++) {
+    const movement = points.map(() => ({x: 0, y: 0}));
+    for (let left = 0; left < points.length; left++) {
+      for (let right = left + 1; right < points.length; right++) {
+        const a = points[left];
+        const b = points[right];
+        const dx = b.x - a.x || .01;
+        const dy = b.y - a.y || .01;
+        const distance = Math.hypot(dx, dy);
+        const score = strengths.get([a.id, b.id].sort().join('|'));
+        const target = score === undefined ? 225 : 220 + (1 - score) * 240;
+        if (score === undefined && distance > target) continue;
+        const force = (distance - target) * (score === undefined ? .045 : .022);
+        const mx = force * dx / distance;
+        const my = force * dy / distance;
+        movement[left].x += mx;
+        movement[left].y += my;
+        movement[right].x -= mx;
+        movement[right].y -= my;
+      }
+    }
+    for (const rule of constraints) {
+      const ai = lookup.get(rule.anchor);
+      const ci = lookup.get(rule.closer);
+      const fi = lookup.get(rule.farther);
+      if (ai === undefined || ci === undefined || fi === undefined) continue;
+      const anchor = points[ai];
+      const closer = points[ci];
+      const farther = points[fi];
+      const closeDistance = Math.hypot(closer.x - anchor.x, closer.y - anchor.y);
+      const farDistance = Math.hypot(farther.x - anchor.x, farther.y - anchor.y);
+      if (closeDistance + 35 < farDistance) continue;
+      const push = Math.min(9, (closeDistance + 35 - farDistance) * .08);
